      const X = k => X0 + (k - min) / (max - min) * TW, cur = p.modo === 'lado' ? s.s : s.e;
      h += `<line class="xb-rule" x1="${X0}" y1="${TY}" x2="${X0 + TW}" y2="${TY}"/>`;
      for (let k = min; k <= max; k++) h += `<line class="xb-tk" x1="${X(k)}" y1="${TY - 4}" x2="${X(k)}" y2="${TY + 4}"/>`;
